	"yclf/dash360/metacompromisso/i18n/i18n_en.properties":'appTitle=Meta e Compromisso\nappDescription=Daily monitoring of targets, commitment, billing and portfolio\ndashboardTitle=Targets and Commitment Report\nstandardVariant=Standard\nupdatedUntil=Updated through\nsalesTeam=Sales Team\nsalesOffice=Consultant / sales office\nconsultant=Consultant\nretailFamily=Retail Family \ndate=Date\ndateRange=Period\nstartDate=Start date\nendDate=End date\ninvalidDateRange=The start date cannot be later than the end date.\nfiltersApplied=Filters applied\ndataSaved=Change saved locally and totals recalculated\ndailyTracking=Daily tracking\neditHint=Budget and commitment are editable. Changes recalculate indicators and are saved in this browser.\nsegments=Segment management\nsegment=Segment\nbudget=Budget\ncommitment=Commitment\nbilled=Billed to date\nportfolioAndBilled=Monthly portfolio\nmonthlyPortfolio=Monthly portfolio + scheduled\nbalance=Billed + portfolio balance vs. budget\nfamilyQuantityTarget=Target by Retail Family quantity\nfamily=Family\nquota=Budget\ncommitmentQuantity=Commitment\nbilledQuantity=Billed\nportfolioQuantity=Monthly portfolio + scheduled\nportfolioAndBilledQuantity=Monthly portfolio\nachievement=% Billed + portfolio vs. budget\nnoData=No records found for the selected filters\nback=Back\nsalesManager=Sales manager\nselectedFamily=Selected family\ntargetVsQuantity=Target vs. Quantity\nconsultantPerformance=Consultant performance\nquotaJune=Budget\nselectedSegment=Selected segment\nportfolioAndBilledValue=Billed + portfolio value\nbusinessDays=Business days month\nelapsedPercentage=% Elapsed\nelapsedDays=Elapsed days\ncommitmentJune=Commitment\naccumulatedOrders=Monthly order entry\ndayEntry=Day entry (day -1)\nremittancePortfolio=Generated remittance\ntotalMonthBalance=Total month balance\n\r\norderCritiques=Portfolio critique\ncritique=Critiques\nquantityShort=Quantity\nvalue=Value\npercentage=% Value by Critique\n',
	"yclf/dash360/metacompromisso/manifest.json":'{"_version":"1.32.0","sap.app":{"id":"yclf.dash360.metacompromisso","type":"application","i18n":{"bundleUrl":"i18n/i18n.properties","supportedLocales":["","en"]},"applicationVersion":{"version":"1.0.0"},"title":"{{appTitle}}","description":"{{appDescription}}"},"sap.ui":{"technology":"UI5","fullWidth":true,"deviceTypes":{"desktop":true,"tablet":true,"phone":true}},"sap.ui5":{"flexEnabled":true,"dependencies":{"minUI5Version":"1.149.1","libs":{"sap.m":{},"sap.ui.core":{},"sap.f":{},"sap.uxap":{},"sap.ui.comp":{},"sap.ui.layout":{}}},"contentDensities":{"compact":true,"cozy":true},"models":{"i18n":{"type":"sap.ui.model.resource.ResourceModel","settings":{"bundleName":"yclf.dash360.metacompromisso.i18n.i18n","fallbackLocale":"","supportedLocales":[""]}}},"resources":{"css":[{"uri":"css/style.css"}]},"routing":{"config":{"routerClass":"sap.m.routing.Router","viewType":"XML","async":true,"viewPath":"yclf.dash360.metacompromisso.view","controlAggregation":"pages","controlId":"app"},"routes":[{"name":"Dashboard","pattern":"","target":"Dashboard"},{"name":"FamilyDetail","pattern":"familia/{familyId}","target":"FamilyDetail"},{"name":"SegmentDetail","pattern":"segmento/{segmentId}","target":"SegmentDetail"}],"targets":{"Dashboard":{"viewName":"Dashboard","viewLevel":1},"FamilyDetail":{"viewName":"FamilyDetail","viewLevel":2},"SegmentDetail":{"viewName":"SegmentDetail","viewLevel":2}}},"rootView":{"viewName":"yclf.dash360.metacompromisso.view.App","type":"XML","async":true,"id":"App"},"flexBundle":false}}',
